# UBP Frame of Mind System v4.3.1 (Fraction-Aware)
import json
import os
from fractions import Fraction

class FrameOfMind:
    def __init__(self, frame_id, description="", base_nrci=0.5):
        self.frame_id = frame_id
        self.description = description
        # Convert incoming base_nrci to Fraction
        self.base_nrci = Fraction(base_nrci).limit_denominator()
        self.weights = {}
        self.category_weights = {} 

    def set_weight(self, ubp_id, nrci): 
        self.weights[ubp_id] = Fraction(nrci).limit_denominator()

    def set_category_weight(self, category, nrci): 
        self.category_weights[category] = Fraction(nrci).limit_denominator()

    def get_weight(self, ubp_id, category=None):
        if ubp_id in self.weights: return self.weights[ubp_id]
        if category and category in self.category_weights: return self.category_weights[category]
        return self.base_nrci

    def to_dict(self): 
        # Export as p/q strings for Bridge Compatibility
        return {
            'frame_id': self.frame_id, 
            'description': self.description, 
            'base_nrci': f"{self.base_nrci.numerator}/{self.base_nrci.denominator}", 
            'weights': {k: f"{v.numerator}/{v.denominator}" for k, v in self.weights.items()},
            'category_weights': {k: f"{v.numerator}/{v.denominator}" for k, v in self.category_weights.items()}
        }

class FOMManager:
    def __init__(self, index_file='ubp_fom_index.json'):
        self.frames = {}; self.active_frame = None; self.index_file = index_file; self.load_index()

    def load_index(self):
        try:
            if os.path.exists(self.index_file):
                with open(self.index_file, 'r') as f:
                    data = json.load(f)
                    # Handle both List and Dict formats
                    frames_data = data if isinstance(data, list) else data.values()
                    for f_data in frames_data:
                        fid = f_data.get('frame_id')
                        if fid:
                            frame = FrameOfMind(fid, f_data.get('description', ''), f_data.get('base_nrci', 0.5))
                            # Load weights and convert to Fractions
                            for k, v in f_data.get('weights', {}).items():
                                frame.set_weight(k, v)
                            for k, v in f_data.get('category_weights', {}).items():
                                frame.set_category_weight(k, v)
                            self.frames[fid] = frame
                    if self.frames: self.active_frame = list(self.frames.keys())[0]
            else:
                 self.frames["FOM_DEFAULT"] = FrameOfMind("FOM_DEFAULT", "Balanced Standard Bias", 0.5)
                 self.active_frame = "FOM_DEFAULT"
        except Exception as e: print(f"[FOM] Error loading index: {e}")

    def save_index(self):
        try:
             data = [f.to_dict() for f in self.frames.values()]
             with open(self.index_file, 'w') as f: json.dump(data, f, indent=4)
        except Exception as e: print(f"[FOM] Error saving: {e}")

    def switch_frame(self, frame_id):
        if frame_id in self.frames: self.active_frame = frame_id; return True
        return False

    def get_active_frame(self): return self.frames[self.active_frame] if (self.active_frame and self.active_frame in self.frames) else None
    def get_mass(self, ubp_id, category=None): return self.get_active_frame().get_weight(ubp_id, category) if self.get_active_frame() else Fraction(1, 2)

FOM_MANAGER = FOMManager()

"""
UBP FRAME OF MIND (FOM) ENGINE v4.2.7 (Synchronized)
====================================================
Implements dynamic NRCI weighting and Contextual Gravity.
Synchronized with ubp_fom_system.py standards.

Author: E R A Craig, New Zealand and the UBP Research Cortex v4.2.7
Date: 3 Feb 2026
"""

import json
import hashlib
from fractions import Fraction
from typing import Dict, List, Any, Optional
from ubp_core_v4_2_6_COMBINED import GOLAY_DECODER, BinaryLinearAlgebra

# --- 1. THE FRAME CONTAINER ---
class FrameOfMind:
    def __init__(self, frame_id: str, description: str = ""):
        self.frame_id = frame_id
        self.description = description
        self.weights: Dict[str, Fraction] = {} 
        self.base_nrci = Fraction(1, 2)

    def set_weight(self, ubp_id: str, nrci: Fraction):
        self.weights[ubp_id] = nrci

    def get_weight(self, ubp_id: str) -> Fraction:
        return self.weights.get(ubp_id, self.base_nrci)

    def export_frame(self) -> str:
        def ubp_json_serializer(obj):
            if isinstance(obj, Fraction):
                return f"{obj.numerator}/{obj.denominator}"
            raise TypeError(f"Type {type(obj)} not serializable")

        data = {
            "frame_id": self.frame_id,
            "description": self.description,
            "base_nrci": self.base_nrci,
            "weights": self.weights
        }
        return json.dumps(data, indent=2, default=ubp_json_serializer)

# --- 2. THE GRAVITATIONAL CORTEX ---
class GravitationalCortex:
    def __init__(self):
        self.golay = GOLAY_DECODER
        self.anchors: Dict[str, List[int]] = {}
        self.active_frame = FrameOfMind("DEFAULT")
        self.EVENT_HORIZON = Fraction(1, 200) 

    def load_anchor(self, ubp_id: str, vector: List[int]):
        self.anchors[ubp_id] = vector

    def set_frame(self, frame):
        # Support both local FrameOfMind and System FrameOfMind objects
        fid = getattr(frame, 'frame_id', getattr(frame, 'name', 'UNKNOWN'))
        print(f"\n[CORTEX] Shifting Frame of Mind to: {fid}")
        self.active_frame = frame

    def vectorize(self, text: str) -> List[int]:
        h = hashlib.sha256(text.encode('utf-8')).hexdigest()
        val = int(h[:6], 16)
        return [(val >> i) & 1 for i in range(23, -1, -1)]

    def observe(self, concept: str):
        fid = getattr(self.active_frame, 'frame_id', 'DEFAULT')
        print(f"\n[OBSERVER] Analyzing: '{concept}' (Frame: {fid})")

        h = hashlib.sha256(concept.encode('utf-8')).hexdigest()
        input_int = int(h[:6], 16)

        best_anchor = None
        max_pull = Fraction(-1, 1)

        for uid, vec in self.anchors.items():
            anchor_int = BinaryLinearAlgebra.list_to_int(vec)
            dist = BinaryLinearAlgebra.fast_hamming(input_int, anchor_int)

            # Use the system-standard get_weight method
            mass = self.active_frame.get_weight(uid)
            pull = mass / ((dist + 1) ** 2)

            if pull > max_pull:
                max_pull = pull
                best_anchor = uid

        if max_pull >= self.EVENT_HORIZON:
            print(f"  [!] CAPTURE: Snapped to '{best_anchor}' (Pull {float(max_pull):.4f})")
            return best_anchor
        else:
            print(f"  [?] FREE FLOATING: No anchor had sufficient gravity.")
            return None

"""
MathAtlas v4.0 - The Definitive Mathematical Substrate
======================================================
Consolidated from v1.3, v2.0, and v3.0.

"Every object is a recursive construction of its own history."

Author: E R A Craig / UBP Research Cortex v4.2.7
Date: 13 February 2026
"""

import json
import hashlib
import decimal
import math
import numpy as np
from fractions import Fraction
from dataclasses import dataclass, field
from typing import List, Tuple, Optional, Dict, Any, Union, Set

# --- UBP CORE INTEGRATION ---
try:
    from ubp_core_v5_3_merged import GOLAY_ENGINE as GOLAY_DECODER
    CORE_AVAILABLE = True
except ImportError:
    CORE_AVAILABLE = False

# --- THE UNIVERSAL CONSTANT ---
UNIVERSAL_NORTH = np.array([-0.30656966974248284, -0.9197090092274486, 0.2452557357939863])
decimal.getcontext().prec = 300 

class MathAtlasConstants:
    """Ultra-high precision mathematical constants for v4.0."""

    @classmethod
    def _cf_to_fraction(cls, cf, depth=100):
        x = Fraction(cf[-1], 1)
        for c in reversed(cf[:-1]): 
            x = Fraction(c, 1) + Fraction(1, x)
        return x

    @classmethod
    def get_pi(cls) -> Fraction:
        cf = [3, 7, 15, 1, 292, 1, 1, 1, 2, 1, 3, 1, 14, 2, 1, 1, 2, 2, 2, 2, 1, 84, 2, 1, 1, 15, 3, 13, 1, 4, 2, 6, 6, 99, 1, 2, 2, 6, 3, 5, 1, 1, 6, 8, 1, 7, 1, 6, 1, 99, 7, 4, 1, 3, 3, 1, 4, 1]
        return cls._cf_to_fraction(cf)

    @classmethod
    def get_e(cls) -> Fraction:
        cf = [2] + [x for n in range(1, 30) for x in [1, 2*n, 1]]
        return cls._cf_to_fraction(cf)

    @classmethod
    def get_phi(cls) -> Fraction:
        return cls._cf_to_fraction([1]*100)

    @classmethod
    def get_sqrt(cls, n) -> Fraction:
        # Newton's method for rational sqrt
        x = Fraction(n, 1)
        for _ in range(10): x = (x + n/x) / 2
        return x

# Pre-compute
PI = MathAtlasConstants.get_pi()
E = MathAtlasConstants.get_e()
PHI = MathAtlasConstants.get_phi()
Y_CONST = Fraction(1, 1) / (PI + Fraction(2, 1)/PI)

@dataclass
class ConstructionPath:
    """A specific geometric construction for a MathObject."""
    primitives: List[Tuple]
    method: str
    tax: Fraction = field(init=False)
    voxels: List[Tuple] = field(init=False, default_factory=list)

    def __post_init__(self):
        self._build(offset=(0,0,0))

    def _build(self, offset):
        total_tax = Fraction(0, 1)
        x, y, z = offset
        for op_tuple in self.primitives:
            op = op_tuple[0]
            if op == 'D':
                mag = op_tuple[1] if len(op_tuple) > 1 else 1
                for _ in range(mag):
                    x += 1; self.voxels.append((x, y, z, "#00ffff")); total_tax += Y_CONST
            elif op == 'X':
                mag = op_tuple[1] if len(op_tuple) > 1 else 1
                for _ in range(mag):
                    x -= 1; self.voxels.append((x, y, z, "#ff0000")); total_tax += Y_CONST
            elif op in ['N', 'J']:
                child = op_tuple[1]
                # Recursive build
                child_offset = (x, y+1, z) if op == 'N' else (x, y, z+1)
                if hasattr(child, 'get_canonical_path'):
                    cp = child.get_canonical_path()
                    for vx, vy, vz, c in cp.voxels:
                        self.voxels.append((child_offset[0]+vx, child_offset[1]+vy, child_offset[2]+vz, c))
                    total_tax += cp.tax + (Y_CONST / (2 if op == 'N' else 4))
        self.tax = total_tax + Fraction(len(self.voxels)**2, 800)

@dataclass
class MathObjectV4:
    ubp_id: str
    name: str
    description: str
    category: str = "math.general"
    paths: List[ConstructionPath] = field(default_factory=list)
    components: Dict[str, 'MathObjectV4'] = field(default_factory=dict)
    morphisms: Dict[str, str] = field(default_factory=dict)
    properties: Dict[str, Any] = field(default_factory=dict)

    def add_path(self, primitives, method):
        path = ConstructionPath(primitives, method)
        self.paths.append(path)
        return path

    def get_canonical_path(self) -> ConstructionPath:
        return min(self.paths, key=lambda p: p.tax) if self.paths else ConstructionPath([], 'empty')

    def get_vector(self) -> List[int]:
        if not CORE_AVAILABLE: return [0]*24
        geo_str = str(sorted(list(set(self.get_canonical_path().voxels))))
        h = hashlib.sha256(geo_str.encode()).digest()
        msg_int = ((h[0] << 8) | h[1]) & 0xFFF
        return GOLAY_DECODER.encode([(msg_int >> i) & 1 for i in range(11, -1, -1)])

    def get_charge(self) -> float:
        vec = self.get_vector()
        o = np.array([float(sum(vec[0:8])-4), float(sum(vec[8:16])-4), float(sum(vec[16:24])-4)])
        mag = np.linalg.norm(o)
        if mag == 0: return 0.0
        unit_north = UNIVERSAL_NORTH / np.linalg.norm(UNIVERSAL_NORTH)
        cos_theta = np.dot(o, unit_north) / mag
        return math.degrees(math.acos(max(-1, min(1, cos_theta))))

    def get_recursive_math(self) -> str:
        """Builds the full embedded math string."""
        if not self.components: return self.properties.get('math_raw', f"Val={self.name}")
        parts = [f"{k}=[{v.get_recursive_math()}]" for k, v in self.components.items()]
        return "|".join(parts)

    def to_dict(self) -> Dict:
        cp = self.get_canonical_path()
        nrci = Fraction(1, 1) / (Fraction(1, 1) + (cp.tax * Fraction(1, 10)))
        return {
            "ubp_id": self.ubp_id,
            "name": self.name,
            "math": self.get_recursive_math(),
            "category": self.category,
            "nrci": f"{nrci.numerator}/{nrci.denominator}",
            "nrci_score": float(nrci),
            "vector": self.get_vector(),
            "geometric_charge": self.get_charge(),
            "atlas_metadata": {
                "voxels": len(cp.voxels),
                "tax": {"n": cp.tax.numerator, "d": cp.tax.denominator},
                "path_count": len(self.paths)
            }
        }

# --- CONSTRUCTORS ---

def PositiveInteger(n: int) -> MathObjectV4:
    obj = MathObjectV4(f"MATH_NAT_{n:010d}", f"Natural {n}", f"The number {n}", "number.natural")
    obj.add_path([('D', n)], 'direct')
    obj.properties['math_raw'] = f"Val={n}"
    return obj

def Rational(p: int, q: int) -> MathObjectV4:
    num = PositiveInteger(p); den = PositiveInteger(q)
    obj = MathObjectV4(f"MATH_RAT_{p}_{q}", f"Rational {p}/{q}", f"The fraction {p}/{q}", "number.rational")
    obj.components = {"num": num, "den": den}
    obj.add_path([('N', num), ('J', den)], 'nested')
    return obj

class ExactRationalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Fraction): return {"n": obj.numerator, "d": obj.denominator, "v": float(obj)}
        if isinstance(obj, MathObjectV4): return obj.to_dict()
        return super().default(obj)

"""
UBP Metrics (Exact) v4.x
=======================

Version: 4
Author: Euan R A Craig, New Zealand
Date: 02 January 2026

Goal: strict float-free metrics suitable for core UBP logic.

Design rules:
- No floats, no UBPUltimateSubstrate.get_pi(50), no numpy.
- All computations return Fractions (or ints / enums).
- π is represented as a rational approximation derived from *integer* continued fraction coefficients.
  This keeps the entire system float-free while remaining deterministic and reproducible.

IMPORTANT:
- If you want an absolutely symbolic π (unevaluated), replace `pi_approx()` usage with an expression
  object of your choice. This module keeps things runnable without external dependencies.
"""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from fractions import Fraction
from typing import Dict, Optional

class CoherenceRegime(Enum):
    ONBIT = "OnBit"               # NRCI >= target
    COHERENT = "Coherent"         # 1/2 <= NRCI < target
    TRANSITIONAL = "Transitional" # 1/10 <= NRCI < 1/2
    SUBCOHERENT = "Subcoherent"   # NRCI < 1/10

# Continued-fraction coefficients for π: [3; 7, 15, 1, 292, 1, 1, 1, 2, 1, 3, 1, 14, ...]
_PI_CF = [3, 7, 15, 1, 292, 1, 1, 1, 2, 1, 3, 1, 14, 2, 1, 1, 2, 2, 2, 2, 1, 84, 2, 1, 1, 15]

def _cf_to_fraction(a) -> Fraction:
    """Convert continued fraction coefficients to a Fraction, exact."""
    if not a:
        raise ValueError("continued fraction coefficients empty")
    x = Fraction(a[-1], 1)
    for c in reversed(a[:-1]):
        x = Fraction(c, 1) + Fraction(1, x)
    return x

def pi_approx(terms: int = 10) -> Fraction:
    """
    Deterministic rational approximation of π using `terms` CF coefficients.
    terms=5 gives 355/113.
    """
    if terms < 1:
        raise ValueError("terms must be >= 1")
    terms = min(terms, len(_PI_CF))
    return _cf_to_fraction(_PI_CF[:terms])

@dataclass(frozen=True)
class UBPConstantsExact:
    PI_TERMS: int = 6  
    PGCI_TARGET: Fraction = Fraction(9999999, 10000000)  

    def pi(self) -> Fraction:
        return pi_approx(self.PI_TERMS)

    def observer_fixed_point(self) -> Fraction:
        p = self.pi()
        return p + Fraction(2, 1) / p

    def y_constant(self) -> Fraction:
        return Fraction(1, 1) / self.observer_fixed_point()

class UBPObserverExact:
    def __init__(self, c: UBPConstantsExact):
        self.c = c

    def get_base_cost(self) -> Fraction:
        return self.c.observer_fixed_point()

    def calculate_realm_cost(self, realm_complexity: Fraction = Fraction(1,1), dimensions: int = 6) -> Fraction:
        return self.get_base_cost() * realm_complexity * Fraction(dimensions, 6)

class UBPCoherenceExact:
    @staticmethod
    def clamp01(x: Fraction) -> Fraction:
        if x < 0: return Fraction(0,1)
        if x > 1: return Fraction(1,1)
        return x

    @staticmethod
    def calculate_nrci(observed_variance: Fraction, theoretical_variance: Fraction = Fraction(1,1)) -> Fraction:
        if theoretical_variance == 0:
            raise ZeroDivisionError("theoretical_variance must be nonzero")
        return UBPCoherenceExact.clamp01(Fraction(1,1) - (observed_variance / theoretical_variance))

    @staticmethod
    def get_regime(nrci_value: Fraction, target: Fraction) -> CoherenceRegime:
        if nrci_value >= target: return CoherenceRegime.ONBIT
        if nrci_value >= Fraction(1,2): return CoherenceRegime.COHERENT
        if nrci_value >= Fraction(1,10): return CoherenceRegime.TRANSITIONAL
        return CoherenceRegime.SUBCOHERENT

class UBPMetricsExact:
    def __init__(self, constants: Optional[UBPConstantsExact] = None):
        self.constants = constants or UBPConstantsExact()
        self.observer = UBPObserverExact(self.constants)
        self.coherence = UBPCoherenceExact()

    def analyze_state(self, variance: Fraction, realm: str = "standard") -> Dict[str, object]:
        nrci = self.coherence.calculate_nrci(variance)
        regime = self.coherence.get_regime(nrci, self.constants.PGCI_TARGET)
        return {
            "nrci": nrci,
            "regime": regime.value,
            "observer_cost": self.observer.get_base_cost(),
            "is_stable": nrci >= Fraction(1,2),
        }

METRICS_EXACT = UBPMetricsExact()

#!/usr/bin/env python3
"""
================================================================================
UBP BRAIN CONSOLIDATED v2 - FIXED VECTOR RETRIEVAL
================================================================================
FIX: Robust vector extraction from KB entries with multiple field name support
     Added debugging to trace vector retrieval issues

Author: Euan R A Craig, New Zealand
Date: 17 February 2026
Version: 2 (Grok X AI ubp V5 assisted)
================================================================================
"""

from fractions import Fraction
from dataclasses import dataclass, field
from typing import List, Tuple, Dict, Optional, Any, Set
from datetime import datetime
import json
import hashlib
import os
import re

# Import from UBP Core Foundation
try:
