    print("[WARNING] UBP Core v5.3 not found. Running in fallback mode.")

# ==============================================================================
# SECTION 1: DATA STRUCTURES
# ==============================================================================

@dataclass
class UBPConcept:
    """A single concept in the UBP ontology."""
    ubp_id: str
    name: str
    vector: List[int]
    category: str
    math: str
    nrci: Fraction
    tax: Fraction
